// DecodeReceivedMessage works out which incoming message data is and decodes
// it. It fails with asyncapirt.ErrUnknownMessage when nothing matches and
// asyncapirt.ErrAmbiguousMessage when several messages match.
func DecodeReceivedMessage(data []byte) (ReceivedMessage, error) {
	name, payload, err := asyncapirt.DecodeMessage(data, receivedMessages)
	if err != nil {
		return ReceivedMessage{}, ctxerrors.Wrap(err, "decode received message")
	}

	return ReceivedMessage{Name: name, Payload: payload}, nil
}

// Handler receives incoming messages. Embed UnimplementedHandler to implement
// only the methods you need.
type Handler interface {
	// Kalshi sends Ping (0x9) with body 'heartbeat' to elicit Pong from client
	// Payload: string.
	// Content type: application/octet-stream.
	HandleOutgoingPing(ctx context.Context, payload string) error
	// Kalshi responds to client Ping with Pong frame (0xA)
	// Payload: string.
	// Content type: application/octet-stream.
	HandleOutgoingPong(ctx context.Context, payload string) error
	// Confirmation that subscription was successful
	// Payload: SubscribedResponsePayload.
	// Content type: application/json.
	HandleSubscribedResponse(ctx context.Context, payload SubscribedResponsePayload) error
	// Confirmation that unsubscription was successful
	// Payload: UnsubscribedResponsePayload.
	// Content type: application/json.
	HandleUnsubscribedResponse(ctx context.Context, payload UnsubscribedResponsePayload) error
	// Successful update operation response
	// Payload: OkResponsePayload.
	// Content type: application/json.
	HandleOkResponse(ctx context.Context, payload OkResponsePayload) error
	// Current Pyth underlying ticker filter after an update; all-mode is ["all"]
	// Payload: SubscribedUnderlyingsResponsePayload.
	// Content type: application/json.
	HandleSubscribedUnderlyingsResponse(ctx context.Context, payload SubscribedUnderlyingsResponsePayload) error
	// Current CF Benchmarks index filter after an update; all-mode is ["all"]
	// Payload: SubscribedIndicesResponsePayload.
	// Content type: application/json.
	HandleSubscribedIndicesResponse(ctx context.Context, payload SubscribedIndicesResponsePayload) error
	// Response containing all active subscriptions
	// Payload: ListSubscriptionsResponsePayload.
	// Content type: application/json.
	HandleListSubscriptionsResponse(ctx context.Context, payload ListSubscriptionsResponsePayload) error
	// Error response for failed operations
	// Payload: ErrorResponsePayload.
	// Content type: application/json.
	HandleErrorResponse(ctx context.Context, payload ErrorResponsePayload) error
	// Complete view of the order book's aggregated price levels
	// Payload: OrderbookSnapshotPayload.
	// Content type: application/json.
	HandleOrderbookSnapshot(ctx context.Context, payload OrderbookSnapshotPayload) error
	// Update to be applied to the current order book view
	// Payload: OrderbookDeltaPayload.
	// Content type: application/json.
	HandleOrderbookDelta(ctx context.Context, payload OrderbookDeltaPayload) error
	// Market price ticker information
	// Payload: TickerPayload.
	// Content type: application/json.
	HandleTicker(ctx context.Context, payload TickerPayload) error
	// Public trade information
	// Payload: TradePayload.
	// Content type: application/json.
	HandleTrade(ctx context.Context, payload TradePayload) error
	// Private fill information for authenticated user
	// Payload: FillPayload.
	// Content type: application/json.
	HandleFill(ctx context.Context, payload FillPayload) error
	// Real-time position updates for authenticated user
	// Payload: MarketPositionPayload.
	// Content type: application/json.
	HandleMarketPosition(ctx context.Context, payload MarketPositionPayload) error
	// Market lifecycle events (created, activated, deactivated, close_date_updated, determined, settled, price_level_structure_updated)
	// Payload: MarketLifecycleV2Payload.
	// Content type: application/json.
	HandleMarketLifecycleV2(ctx context.Context, payload MarketLifecycleV2Payload) error
	// Updated strike information or yes subtitle
	// Payload: MarketMetadataUpdatedPayload.
	// Content type: application/json.
	HandleMarketMetadataUpdated(ctx context.Context, payload MarketMetadataUpdatedPayload) error
	// Event creation notification
	// Payload: EventLifecyclePayload.
	// Content type: application/json.
	HandleEventLifecycle(ctx context.Context, payload EventLifecyclePayload) error
	// Emitted when an event-level fee override is set or cleared
	// Payload: EventFeeUpdatePayload.
	// Content type: application/json.
	HandleEventFeeUpdate(ctx context.Context, payload EventFeeUpdatePayload) error
	// Multivariate market lifecycle events (created, activated, deactivated, close_date_updated, determined, settled)
	// Payload: MultivariateMarketLifecyclePayload.
	// Content type: application/json.
	HandleMultivariateMarketLifecycle(ctx context.Context, payload MultivariateMarketLifecyclePayload) error
	// Notification when an RFQ is created
	// Payload: RfqCreatedPayload.
	// Content type: application/json.
	HandleRfqCreated(ctx context.Context, payload RfqCreatedPayload) error
	// Notification when an RFQ is deleted
	// Payload: RfqDeletedPayload.
	// Content type: application/json.
	HandleRfqDeleted(ctx context.Context, payload RfqDeletedPayload) error
	// Notification when a quote is created on an RFQ
	// Payload: QuoteCreatedPayload.
	// Content type: application/json.
	HandleQuoteCreated(ctx context.Context, payload QuoteCreatedPayload) error
	// Notification when a quote is accepted
	// Payload: QuoteAcceptedPayload.
	// Content type: application/json.
	HandleQuoteAccepted(ctx context.Context, payload QuoteAcceptedPayload) error
	// Notification when a quote is executed and orders are placed
	// Payload: QuoteExecutedPayload.
	// Content type: application/json.
	HandleQuoteExecuted(ctx context.Context, payload QuoteExecutedPayload) error
	// Notification when an RFQ batch is created
	// Payload: RfqBatchCreatedPayload.
	// Content type: application/json.
	HandleRfqBatchCreated(ctx context.Context, payload RfqBatchCreatedPayload) error
	// Notification when an RFQ batch closes
	// Payload: RfqBatchDeletedPayload.
	// Content type: application/json.
	HandleRfqBatchDeleted(ctx context.Context, payload RfqBatchDeletedPayload) error
	// Notification when you create a batch quote on an RFQ batch
	// Payload: BatchQuoteCreatedPayload.
	// Content type: application/json.
	HandleBatchQuoteCreated(ctx context.Context, payload BatchQuoteCreatedPayload) error
	// The best quotes across makers on your RFQ batch
	// Payload: RfqBatchBestQuotesPayload.
	// Content type: application/json.
	HandleRfqBatchBestQuotes(ctx context.Context, payload RfqBatchBestQuotesPayload) error
	// Notification when your batch quote wins children of an accepted RFQ batch
	// Payload: BatchQuoteAcceptedPayload.
	// Content type: application/json.
	HandleBatchQuoteAccepted(ctx context.Context, payload BatchQuoteAcceptedPayload) error
	// Notification when your accepted RFQ batch has executed or failed
	// Payload: RfqBatchExecutedPayload.
	// Content type: application/json.
	HandleRfqBatchExecuted(ctx context.Context, payload RfqBatchExecutedPayload) error
	// Notification when the RFQ batch your batch quote won children of has executed or failed
	// Payload: BatchQuoteExecutedPayload.
	// Content type: application/json.
	HandleBatchQuoteExecuted(ctx context.Context, payload BatchQuoteExecutedPayload) error
	// Order group lifecycle and limit updates for authenticated user
	// Payload: OrderGroupUpdatesPayload.
	// Content type: application/json.
	HandleOrderGroupUpdates(ctx context.Context, payload OrderGroupUpdatesPayload) error
	// Real-time order updates for authenticated user
	// Payload: UserOrderPayload.
	// Content type: application/json.
	HandleUserOrder(ctx context.Context, payload UserOrderPayload) error
	// Real-time CF Benchmarks index value with trailing 60-second and quarter-hour averages
	// Payload: CfbenchmarksValuePayload.
	// Content type: application/json.
	HandleCfbenchmarksValue(ctx context.Context, payload CfbenchmarksValuePayload) error
	// The set of available CF Benchmarks index IDs, sent in response to an indexlist action
	// Payload: CfbenchmarksIndexListPayload.
	// Content type: application/json.
	HandleCfbenchmarksIndexList(ctx context.Context, payload CfbenchmarksIndexListPayload) error
	// Real-time CF Benchmarks index value at up to 5 updates per second
	// Payload: CfbenchmarksValue5HzPayload.
	// Content type: application/json.
	HandleCfbenchmarksValue5Hz(ctx context.Context, payload CfbenchmarksValue5HzPayload) error
	// The index IDs recently observed on the 5Hz stream, sent in response to an indexlist action
	// Payload: Cfbenchmarks5HzIndexListPayload.
	// Content type: application/json.
	HandleCfbenchmarks5HzIndexList(ctx context.Context, payload Cfbenchmarks5HzIndexListPayload) error
	// Deduplicated real-time Pyth price or Treasury yield for an underlying ticker
	// Payload: PythValuePayload.
	// Content type: application/json.
	HandlePythValue(ctx context.Context, payload PythValuePayload) error
	// Recently streamed Pyth underlying tickers
	// Payload: PythUnderlyingListPayload.
	// Content type: application/json.
	HandlePythUnderlyingList(ctx context.Context, payload PythUnderlyingListPayload) error
	// HandleUnknownMessage gets every message that matched nothing, with the
	// reason. Returning an error stops Client.Run.
	HandleUnknownMessage(ctx context.Context, data []byte, err error) error
}

